export type Options<TData extends TDataShape = TDataShape, ThrowOnError extends boolean = boolean> = Options2<TData, ThrowOnError> & {
    /**
     * You can provide a client instance returned by `createClient()` instead of
     * individual options. This might be also useful if you want to implement a
     * custom client.
     */
    client?: Client;
    /**
     * You can pass arbitrary values through the `meta` object. This can be
     * used to access values that aren't defined as part of the SDK function.
     */
    meta?: Record<string, unknown>;
};

/**
 * Tenant Info
 *
 * Retrieve workspace preferences including name, timezone, default currency,
 * country, and business rules. Use this to understand the current workspace
 * configuration before making changes.
 */
export const tenantInfo = <ThrowOnError extends boolean = false>(options: Options<TenantInfoData, ThrowOnError>) => (options.client ?? client).get<TenantInfoResponses, unknown, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }, {
            in: 'cookie',
            name: 'sessionid',
            type: 'apiKey'
        }],
    url: '/api/v1/{tenant_path}/tenant_info',
    ...options
});

